  fun resolve(preference: String, tags: List<String>): String {
    if (preference in supported) return preference
    for (tag in tags) {
      if (!tag.matches(Regex("[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*"))) continue
      val parts = tag.lowercase(java.util.Locale.ROOT).split('-')
      if (parts[0] == "zh") {
        val script = parts.firstOrNull { it == "hans" || it == "hant" }
        return if (script == "hant" || (script == null && parts.any { it in setOf("tw", "hk", "mo") })) "zh-Hant" else "zh-Hans"
      }
      if (parts[0] in supported) return parts[0]
    }
    return "en"
  }
  fun text(locale: String, key: String): String = copy[locale]?.get(key) ?: copy.getValue("en").getValue(key)
  fun formatTag(preference: String, tags: List<String>): String {
    if (preference in supported) return preference
    return tags.firstOrNull { tag ->
      tag.matches(Regex("[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*")) &&
        (tag.substringBefore('-').lowercase(java.util.Locale.ROOT).let { it == "zh" || it in supported })
    } ?: "en"
  }
  fun title(locale: String, id: String?): String = titles[locale]?.get(id) ?: text(locale, "native.widget.name")
  fun accessibility(locale: String, date: String, title: String): String = text(locale, "native.widget.accessibility").replace("{date}", date).replace("{title}", title)
  private val blessingIds = listOf("nanakusa-gayu", "brat-bride-cloth", "korean-sotdae", "japanese-kadomatsu", "pucara-rooftop-bulls", "chinese-longevity-lock", "uchide-wishing-mallet", "yusheng-lohei", "kitano-nadeushi", "lao-baci-wrist", "finnish-virpominen", "scottish-first-footing", "hiiragi-iwashi", "tamagushi-offering", "tibetan-water-bowls", "kagami-biraki-sake", "tibetan-prayer-flags", "rosh-hashanah-apple-honey", "thai-songkran-elders", "kameido-usokae", "persian-esfand", "mochigase-nagashibina", "greek-vasilopita", "tibetan-khata-greeting", "shichigosan-chitose-ame", "mongolian-ovoo", "fgs-buddha-bathing", "balinese-canang-sari", "bulgarian-survakane", "lanna-sand-pagoda", "chinese-fu-paper", "turkish-nazar-bead", "japanese-hamaya", "vietnamese-five-fruit-tray", "chinese-ruyi-scepter", "japanese-kumade", "neapolitan-cornicello", "spanish-twelve-grapes", "horseshoe-doorway-luck", "setsubun-mamemaki", "sternsinger-house-blessing", "kagami-mochi-offering", "romanian-martisor", "polish-oplatek-sharing", "greek-new-year-pomegranate", "bonfim-ribbon", "chinowa-kuguri", "woodfish", "furin-wind-chime", "shinto-torii", "tibetan-wheel", "clootie-well-rag", "diya-oil-lamp", "shrine-suzu-bell", "st-brigids-cross", "bokjori", "omikuji", "navruz-sumalak", "chinese-incense", "lithuanian-straw-garden", "japanese-koinobori")
  private val wishIds = listOf("alasita-miniature-house", "lam-tsuen-wishing-tree", "sumiyoshi-godairiki", "zeniarai-coin-washing", "udo-undama", "tanzaku-tanabata", "yeondeunghoe", "crane", "slavic-wreath", "daruma-eye-painting", "mizuhiki", "milagros", "phuang-malai", "ema-votive-plaque", "votive-candle-catholic", "omamori-cycle", "polish-blessing-basket", "floating-lantern-loy-krathong", "italian-ex-voto", "aland-votive-ship", "sorbian-painted-egg", "basque-sunflower", "barcelos-clay-rooster", "croatian-licitar-heart", "welsh-love-spoon", "korean-bojagi-wrap")
  fun dailyScene(day: String, excluded: List<String> = emptyList()): String? {
    val blessings = blessingIds.filterNot { it in excluded }
    val wishes = wishIds.filterNot { it in excluded }
    val pool = (0 until maxOf(blessings.size, wishes.size)).flatMap { listOfNotNull(blessings.getOrNull(it), wishes.getOrNull(it)) }
    if (pool.isEmpty()) return null
    val ordinal = Math.floorDiv(WidgetDates.parseDay(day)?.time ?: return null, 86400000L)
    return pool[Math.floorMod(ordinal, pool.size.toLong()).toInt()]
  }
